<script setup lang="ts">
const props=defineProps<{report:any}>();
const rows=computed(()=>{const r=props.report;if(!r?.accounting)return [];const rows=[];const output=r.kpi?.totalTax??r.outwardTaxable?.totalTax,input=r.kpi?.totalItc??r.itc?.totalItc;if(output!==undefined)rows.push({tax:'Output tax',source:output,posted:r.accounting.outputTax,difference:r.accounting.outputTax-output});if(input!==undefined)rows.push({tax:'Input tax',source:input,posted:r.accounting.inputTax,difference:r.accounting.inputTax-input});return rows});
const columns=[{key:'tax',label:'Tax'},{key:'source',label:'Source documents'},{key:'posted',label:'Posted movement'},{key:'difference',label:'Accounting less source'}];
</script>
<template><UCard v-if="rows.length"><template #header>Tax comparison with accounting</template><UTable :rows="rows" :columns="columns"><template #source-data="{row}">{{ Number(row.source).toFixed(2) }}</template><template #posted-data="{row}">{{ Number(row.posted).toFixed(2) }}</template><template #difference-data="{row}">{{ Number(row.difference).toFixed(2) }}</template></UTable><p v-if="Number(report.kpi?.unallocatedInvoiceValue??report.unallocatedInvoiceValue)" class="text-xs mt-2">Invoice value without allocatable item tax detail: {{ Number(report.kpi?.unallocatedInvoiceValue??report.unallocatedInvoiceValue).toFixed(2) }}</p><p class="text-xs text-gray-500 mt-2">Posted input tax also includes recoverable expense tax and journal adjustments. Differences are shown separately; they do not change source tax figures.</p></UCard></template>
